function validate([mat1, mat2]) {
  const shape = (mat) => Array.isArray(mat) && mat.length >= 1 && mat.length <= 100 && mat.every(row => Array.isArray(row) && row.length === mat[0].length) && mat[0].length >= 1 && mat[0].length <= 100;
  if (!shape(mat1) || !shape(mat2)) return 'Each matrix needs 1 to 100 rows of equal length, 1 to 100 columns.';
  if (mat1[0].length !== mat2.length) return 'mat1 needs as many columns as mat2 has rows.';
  for (const mat of [mat1, mat2]) for (const row of mat) for (const v of row) if (!Number.isInteger(v) || v < -100 || v > 100) return 'Every entry is an integer from -100 to 100.';
  return null;
}

