function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 100 : 1 + Math.floor(rand() * 4);
  const k = large ? 90 : 1 + Math.floor(rand() * 4);
  const n = large ? 100 : 1 + Math.floor(rand() * 4);
  const density = large ? 0.1 : [0, 0.3, 0.6, 1][Math.floor(rand() * 4)];
  const span = large || rand() < 0.2 ? 100 : 5;
  const cell = () => {
    if (rand() >= density) return 0;
    const v = Math.floor(rand() * (2 * span + 1)) - span;
    return v === 0 ? 1 : v;
  };
  const make = (rows, cols) => Array.from({ length: rows }, () => Array.from({ length: cols }, cell));
  return [make(m, k), make(k, n)];
}
